package se.smartgallery.app;

import android.app.*;import android.graphics.*;import android.view.*;import android.widget.*;import com.google.android.gms.tasks.Tasks;import com.google.mlkit.vision.common.InputImage;import com.google.mlkit.vision.face.*;import org.tensorflow.lite.Interpreter;import java.io.*;import java.util.*;import java.util.concurrent.TimeUnit;

public class MainActivity19 extends MainActivity18{
 @Override void peoplePage(){String[] a={"👤 Hitta samma person 5.0","🧪 Diagnostik & kalibrering","🧠 Bygg om personindex 5.0","🏷 Namnge person","🔒 Om analysen"};new AlertDialog.Builder(this).setTitle("👥 Personer 5.0").setMessage("1.9 fokuserar på felsökning och högre träffgrad. Markera helst 3–5 säkra bilder av samma person före sökning.").setItems(a,(d,w)->{if(w==0)search19();else if(w==1)diagnose19();else if(w==2)index19(null,true);else if(w==3)namePerson();else new AlertDialog.Builder(this).setTitle("Lokal analys").setMessage("ML Kit hittar ansikten och MobileFaceNet skapar embeddings lokalt. Bilderna lämnar inte telefonen.").setPositiveButton("OK",null).show();}).setNegativeButton("Stäng",null).show();}
 void search19(){ArrayList<Item>r=selectedItems();r.removeIf(Item::video);if(r.isEmpty()){Toast.makeText(this,"Markera 1–5 bilder av samma person",Toast.LENGTH_LONG).show();return;}if(r.size()>5)r=new ArrayList<>(r.subList(0,5));index19(r,false);}
 void diagnose19(){ArrayList<Item>r=selectedItems();r.removeIf(Item::video);if(r.size()<2){Toast.makeText(this,"Markera minst 2 säkra bilder av samma person för kalibrering",Toast.LENGTH_LONG).show();return;}if(r.size()>5)r=new ArrayList<>(r.subList(0,5));final ArrayList<Item>refs=r;ProgressDialog pd=new ProgressDialog(this);pd.setTitle("🧪 Diagnostik");pd.setMessage("Kontrollerar referensbilder…");pd.setCancelable(false);pd.show();pool.execute(()->{Interpreter tf=null;FaceDetector det=null;try{tf=new Interpreter(loadModel18());FaceDetectorOptions o=new FaceDetectorOptions.Builder().setPerformanceMode(FaceDetectorOptions.PERFORMANCE_MODE_ACCURATE).setLandmarkMode(FaceDetectorOptions.LANDMARK_MODE_ALL).setMinFaceSize(.04f).build();det=FaceDetection.getClient(o);ArrayList<float[]>v=new ArrayList<>();int detected=0;for(Item i:refs){ArrayList<float[]>e=embeddings19(faceBitmap(i),det,tf);if(!e.isEmpty()){detected++;v.add(e.get(0));}}float min=1,max=-1,sum=0;int pairs=0;for(int i=0;i<v.size();i++)for(int j=i+1;j<v.size();j++){float s=cos18(v.get(i),v.get(j));min=Math.min(min,s);max=Math.max(max,s);sum+=s;pairs++;}float avg=pairs>0?sum/pairs:0;HashMap<String,ArrayList<float[]>>idx=readEmb18(new File(getFilesDir(),"face-embeddings-v5.txt"));int indexed=idx.size(),faces=0;for(ArrayList<float[]>x:idx.values())faces+=x.size();final int D=detected,I=indexed,F=faces;final float MN=min,AV=avg,MX=max;runOnUiThread(()->{pd.dismiss();new AlertDialog.Builder(this).setTitle("🧪 Persondiagnostik").setMessage("Referensbilder: "+refs.size()+"\nAnsikte hittat: "+D+"\n\nIndexerade bilder: "+I+" av "+all.size()+"\nAnsikten i index: "+F+"\n\nLikhet mellan dina säkra referenser:\nLägst: "+fmt19(MN)+"\nMedel: "+fmt19(AV)+"\nHögst: "+fmt19(MX)+"\n\nOm samma person får låg intern likhet använder 1.9 en adaptiv gräns i stället för en fast hård gräns.").setPositiveButton("OK",null).show();});}catch(Exception e){runOnUiThread(()->{pd.dismiss();Toast.makeText(this,"Diagnostiken misslyckades: "+e.getMessage(),Toast.LENGTH_LONG).show();});}finally{if(det!=null)det.close();if(tf!=null)tf.close();}});}
 String fmt19(float x){return String.format(Locale.ROOT,"%.3f",x);}
 void index19(ArrayList<Item>refs,boolean rebuild){ProgressDialog pd=new ProgressDialog(this);pd.setTitle("🧠 Personer 5.0");pd.setProgressStyle(ProgressDialog.STYLE_HORIZONTAL);pd.setMax(all.size());pd.setCancelable(true);pd.show();final ArrayList<Item>rr=refs;pool.execute(()->{Interpreter tf=null;FaceDetector det=null;try{tf=new Interpreter(loadModel18());FaceDetectorOptions o=new FaceDetectorOptions.Builder().setPerformanceMode(FaceDetectorOptions.PERFORMANCE_MODE_ACCURATE).setLandmarkMode(FaceDetectorOptions.LANDMARK_MODE_ALL).setMinFaceSize(.04f).build();det=FaceDetection.getClient(o);File cache=new File(getFilesDir(),"face-embeddings-v5.txt");HashMap<String,ArrayList<float[]>>idx=rebuild?new HashMap<>():readEmb18(cache);int n=0,faces=0,failed=0;for(Item i:all){if(pd.isCancelled())break;n++;if(!i.video()&&!idx.containsKey(i.uri.toString())){try{ArrayList<float[]>e=embeddings19(faceBitmap(i),det,tf);idx.put(i.uri.toString(),e);faces+=e.size();}catch(Exception e){failed++;}}if(n%8==0){final int N=n,F=faces,X=failed;runOnUiThread(()->{pd.setProgress(N);pd.setMessage("Bild "+N+" / "+all.size()+" • ansikten "+F+" • fel "+X);});}}writeEmb18(cache,idx);if(rr==null){final int F=faces,X=failed;runOnUiThread(()->{pd.dismiss();new AlertDialog.Builder(this).setTitle("Personindex 5.0 klart").setMessage(idx.size()+" bilder indexerade\n"+F+" nya ansikten\n"+X+" analysfel").setPositiveButton("OK",null).show();});return;}ArrayList<float[]>seeds=new ArrayList<>();for(Item r:rr){ArrayList<float[]>e=embeddings19(faceBitmap(r),det,tf);if(!e.isEmpty())seeds.add(e.get(0));}if(seeds.isEmpty())throw new Exception("Inget ansikte i referenserna");float intra=.55f;if(seeds.size()>1){float sum=0;int p=0;for(int i=0;i<seeds.size();i++)for(int j=i+1;j<seeds.size();j++){sum+=cos18(seeds.get(i),seeds.get(j));p++;}if(p>0)intra=sum/p;}float threshold=Math.max(.18f,Math.min(.48f,intra-.18f));HashMap<String,Float>scores=new HashMap<>();for(Map.Entry<String,ArrayList<float[]>>en:idx.entrySet()){float best=-1;for(float[]x:en.getValue())for(float[]s:seeds)best=Math.max(best,cos18(x,s));if(best>=threshold)scores.put(en.getKey(),best);}ArrayList<Item>cand=new ArrayList<>();HashSet<String>seen=new HashSet<>();for(Item i:all)if(scores.containsKey(i.uri.toString())&&seen.add(i.uri.toString()))cand.add(i);cand.sort((a,b)->Float.compare(scores.get(b.uri.toString()),scores.get(a.uri.toString())));float hi=Math.min(.65f,threshold+.22f),mid=Math.min(.54f,threshold+.10f);int A=0,B=0,C=0;for(Item i:cand){float s=scores.get(i.uri.toString());if(s>=hi)A++;else if(s>=mid)B++;else C++;}final int FA=A,FB=B,FC=C;final float FT=threshold,FI=intra;runOnUiThread(()->{pd.dismiss();Toast.makeText(this,"Adaptiv gräns "+fmt19(FT)+" • referenslikhet "+fmt19(FI),Toast.LENGTH_LONG).show();showAdaptiveResults(cand,FA,FB,FC);});}catch(Exception e){final String m=e.getMessage();runOnUiThread(()->{pd.dismiss();new AlertDialog.Builder(this).setTitle("Personer 5.0").setMessage("Analysen kunde inte slutföras\n\n"+m).setPositiveButton("OK",null).show();});}finally{if(det!=null)det.close();if(tf!=null)tf.close();}});}
 ArrayList<float[]> embeddings19(Bitmap b,FaceDetector d,Interpreter tf)throws Exception{ArrayList<float[]>out=new ArrayList<>();if(b==null)return out;List<Face>fs=Tasks.await(d.process(InputImage.fromBitmap(b,0)),30,TimeUnit.SECONDS);int[]shape=tf.getInputTensor(0).shape();int h=shape[1],w=shape[2];int[]os=tf.getOutputTensor(0).shape();int od=1;for(int x:os)od*=x;for(Face f:fs){Rect q=new Rect(f.getBoundingBox());int side=Math.max(q.width(),q.height());int cx=q.centerX(),cy=q.centerY()-(int)(side*.03f);int half=(int)(side*.70f);int l=Math.max(0,cx-half),t=Math.max(0,cy-half),r=Math.min(b.getWidth(),cx+half),bt=Math.min(b.getHeight(),cy+half);if(r-l<20||bt-t<20)continue;Bitmap c=Bitmap.createScaledBitmap(Bitmap.createBitmap(b,l,t,r-l,bt-t),w,h,true);java.nio.ByteBuffer input=java.nio.ByteBuffer.allocateDirect(4*w*h*3).order(java.nio.ByteOrder.nativeOrder());for(int y=0;y<h;y++)for(int x=0;x<w;x++){int z=c.getPixel(x,y);input.putFloat(Color.red(z)/128f-1f);input.putFloat(Color.green(z)/128f-1f);input.putFloat(Color.blue(z)/128f-1f);}input.rewind();float[][]o=new float[1][od];tf.run(input,o);norm18(o[0]);out.add(o[0]);}return out;}
}
